import { useWalletSearchParams } from '~/entities/wallet/lib/use-wallet-search-params';
import { WalletHistoryViewType } from '~/entities/wallet/types';
import { FilterList } from '~/entities/wallet/ui/wallet-history/filter-list';
import { HistoryListContainer } from '~/entities/wallet/ui/wallet-history/history-list-container';
import { SearchAreaInner } from '~/entities/wallet/ui/wallet-history/search-area-inner';
import { WalletSearchParamsProvider } from '~/entities/wallet/ui/wallet-history/wallet-search-params-provider';

type WalletHistoryLayoutProps = {
  viewType: WalletHistoryViewType;
  title: string;
  searchAreaContent?: React.ReactNode;
  additionalParams?: Record<string, string | undefined>;
};

export const WalletHistoryLayout = ({
  viewType,
  title,
  searchAreaContent,
  additionalParams = {},
}: WalletHistoryLayoutProps) => {
  const { getStDt, getEdDt } = useWalletSearchParams();

  return (
    <WalletSearchParamsProvider
      params={{
        stDt: getStDt(),
        edDt: getEdDt(),
        viewType,
        ...additionalParams,
      }}
    >
      <section className="wallet-detail-filter-container">
        <div className="wallet-detail-filter-top">
          {searchAreaContent}
          <SearchAreaInner />
        </div>
        <div className="wallet-detail-filter-bottom">
          <FilterList />
        </div>
      </section>
      <HistoryListContainer title={title} />
    </WalletSearchParamsProvider>
  );
};
