import { SwitchCase } from '@toss/react';
import { Fragment, useCallback, useState } from 'react';
import { useLocation } from 'react-router-dom';
import { useSetIsPullToRefreshEnabled } from '~/widgets/sub-layout/use-sub-layout';
import { WebViewRedirectionBoundary } from '~/widgets/web-view/redirection-boundary';
import {
  ManageMyWalletMoreBottomSheet,
  ManageMyWalletMoreMenuType,
} from '~/entities/menu/ui/manage-my-wallet-more-bottom-sheet';
import { UserWalletResponse } from '~/entities/pin/api/dtos/schemas';
import { TokenItem } from '~/entities/pin/api/dtos/types';
import { useQRScan } from '~/entities/qr-scan/lib/use-qr-scan';
import { useGetUserInfoQuery } from '~/entities/user/api/use-get-cstmr-query';
import { useGetCstmrWalletListQuery } from '~/entities/user/api/use-get-cstmr-wallet-list-query';
import { useRefreshUserInfo } from '~/entities/user/lib/use-refresh-user-info';
import { useDeleteWalletMutation } from '~/entities/wallet/api/use-delete-wallet-mutation';
import { useWalletSearchParams } from '~/entities/wallet/lib/use-wallet-search-params';
import { WalletHistoryViewType } from '~/entities/wallet/types';
import { AssetDetailInfo } from '~/entities/wallet/ui/wallet-history/asset-detail-info';
import { WalletHistoryLayout } from '~/entities/wallet/ui/wallet-history/wallet-history-layout';
import { StepBeforeRegister } from '~/shared/api/dtos/enums';
import i18n from '~/shared/i18n/i18n';
import { useNavigate } from '~/shared/lib/hooks';
import { usePinBottomSheet } from '~/shared/lib/hooks/use-pin-bottom-sheet';
import { overlay } from '~/shared/lib/overlay';
import { PATHS } from '~/shared/routes/paths';
import { closeDialog } from '~/shared/ui/dialogs';
import { Dialog } from '~/shared/ui/dialogs/dialog';

export type TokenHistoryParams = Pick<TokenItem, 'id'>;

export const HistoryPage = () => {
  useSetIsPullToRefreshEnabled(true);
  useRefreshUserInfo();

  const { openQRScanner } = useQRScan();
  const { searchParams } = useWalletSearchParams();
  const { data: walletList = [] } = useGetCstmrWalletListQuery();
  const { data: userRes } = useGetUserInfoQuery();
  const hasBusinessAccount = Boolean(userRes?.tbCstmrMastr?.ewaBizNo);
  const { state } = useLocation();
  const { aliasNm, coinId, coinType, walletInsttCd } = searchParams;
  const { viewType } = searchParams;
  const routeState = (state as { isWalletBlocked?: boolean } | null) ?? {};
  const selectedWallet = walletList.find((wallet) => wallet.aliasNm === aliasNm);
  const isDisabled = selectedWallet?.isWalletBlocked ?? routeState.isWalletBlocked ?? false;

  const { navigate } = useNavigate();
  const { openPinBottomSheet } = usePinBottomSheet();
  const { mutateAsync: deleteWallet } = useDeleteWalletMutation();
  const [isMoreSheetOpen, setIsMoreSheetOpen] = useState(false);

  const handleOpenMoreMenu = useCallback(() => {
    setIsMoreSheetOpen(true);
  }, []);

  const handleCloseMoreMenu = useCallback(() => {
    setIsMoreSheetOpen(false);
  }, []);

  const handleDeleteMyWallet = useCallback(() => {
    if (!selectedWallet) return;

    if ((selectedWallet.acnutnoBlce ?? 0) > 0) {
      overlay.exclusiveOpen(({ isOpen, close, unmount }) => (
        <Dialog
          afterLeave={unmount}
          open={isOpen}
          onClose={close}
          message={
            <Fragment>
              예금 토큰 잔액이 0원인 경우에만
              <br />
              지갑을 삭제할 수 있습니다.
            </Fragment>
          }
        />
      ));
      return;
    }

    overlay.exclusiveOpen(({ isOpen, close, unmount }) => (
      <Dialog
        afterLeave={unmount}
        open={isOpen}
        onClose={close}
        message={i18n.t('validation:walletDeletionConfirmation')}
        buttonLabel={[i18n.t('cancel'), i18n.t('confirm')]}
        onConfirmClick={() => {
          openPinBottomSheet((pinClose) => {
            pinClose();
            setTimeout(async () => {
              await deleteWallet({
                tbCstmrMastr: { walletId: selectedWallet.walletId ?? '' },
              });
            }, 0);
          });
        }}
      />
    ));
  }, [deleteWallet, openPinBottomSheet, selectedWallet]);

  const handleSelectMoreMenu = useCallback(
    (menuType: ManageMyWalletMoreMenuType, menuAliasNm: string) => {
      setIsMoreSheetOpen(false);
      switch (menuType) {
        case 'autoOnOffRampSetting':
          setTimeout(() => navigate(PATHS.setAutoOnOffRamp.root, { state: { aliasNm: menuAliasNm } }), 0);
          break;
        case 'changeToBusinessAccount':
          if (!hasBusinessAccount) {
            overlay.exclusiveOpen(({ isOpen, close, unmount }) => (
              <Dialog
                afterLeave={unmount}
                open={isOpen}
                onClose={close}
                message={i18n.t('validation:changeToBusinessAccountConfirmation')}
                buttonLabel={[i18n.t('cancel'), i18n.t('confirm')]}
                onConfirmClick={() => {
                  closeDialog(() => {
                    navigate(PATHS.myWallet.business, {
                      state: { step: StepBeforeRegister['등록'], aliasNm: menuAliasNm },
                    });
                  });
                }}
              />
            ));
          } else {
            setTimeout(() => {
              navigate(PATHS.myWallet.business, {
                state: { step: StepBeforeRegister['재설정'], aliasNm: menuAliasNm },
              });
            }, 0);
          }
          break;
        case 'deleteWallet':
          handleDeleteMyWallet();
          break;
      }
    },
    [handleDeleteMyWallet, hasBusinessAccount, navigate],
  );

  return (
    <WebViewRedirectionBoundary>
      <div className="page-wallet-detail-KBB">
        <SwitchCase
          value={viewType as WalletHistoryViewType}
          caseBy={{
            [WalletHistoryViewType.TOKEN_HISTORY]: (
              <>
                <AssetDetailInfo
                  coinId={coinId ?? ''}
                  openQRScanner={openQRScanner}
                  isDisabled={isDisabled}
                  selectedWallet={selectedWallet || ({} as UserWalletResponse)}
                  onOpenMoreMenu={handleOpenMoreMenu}
                />
                <WalletHistoryLayout
                  viewType={viewType as WalletHistoryViewType}
                  title={i18n.t('detail')}
                  additionalParams={{
                    coinId: coinId,
                    coinType: coinType,
                    walletInsttCd: walletInsttCd,
                  }}
                />
              </>
            ),
            [WalletHistoryViewType.HISTORY_HISTORY]: (
              <WalletHistoryLayout
                viewType={viewType as WalletHistoryViewType}
                title={i18n.t('viewAllUsageHistory')}
              />
            ),
          }}
          defaultComponent={
            <WalletHistoryLayout
              viewType={viewType as WalletHistoryViewType}
              title={i18n.t('viewAllUsageHistory')}
            />
          }
        />
        <ManageMyWalletMoreBottomSheet
          isSheetOpen={isMoreSheetOpen}
          aliasNm={aliasNm ?? ''}
          wallet={selectedWallet || ({} as UserWalletResponse)}
          hasBusinessAccount={hasBusinessAccount}
          onClose={handleCloseMoreMenu}
          onSelectMenu={handleSelectMoreMenu}
        />
      </div>
    </WebViewRedirectionBoundary>
  );
};
