import { ErrorBoundary, Suspense } from '@suspensive/react';
import { memo } from 'react';
import { FallbackErrorMessage } from '~/widgets/fallbacks/ui/fallback-error-message';
import { useComBankInfo } from '~/entities/comcode/lib/use-com-bank-info';
import { WalletStatus } from '~/entities/home/ui/wallet/wallet-status';
import { UserWalletResponse } from '~/entities/pin/api/dtos/schemas';
import { TOKEN_LABEL } from '~/entities/pin/api/dtos/types';
import { ScannerType } from '~/entities/qr-scan/model/types';
import { getTokenDetailType, findTokenItemById } from '~/entities/user/lib/token-utils';
import { TOKEN_DETAIL_CONFIG } from '~/entities/wallet/model/constants';
import { FunctionButtons } from '~/entities/wallet/ui/token-list/function-buttons';
import { useCopy } from '~/shared/lib/hooks/use-copy';

type Props = {
  coinId: string;
  openQRScanner: (options: { scannerType: ScannerType }) => void;
  isDisabled: boolean;
  selectedWallet: UserWalletResponse;
  onOpenMoreMenu?: () => void;
};

const AssetDetailLoader = ({ coinId, openQRScanner, isDisabled, selectedWallet, onOpenMoreMenu }: Props) => {
  const latestCoinItem = findTokenItemById(selectedWallet.tokenList, coinId);
  const tokenDetailType = getTokenDetailType(selectedWallet.tokenList, coinId);
  const { shortBankName } = useComBankInfo(latestCoinItem?.bankCd ?? '');
  const { copyWalletAddress } = useCopy();

  return (
    <>
      <section className="wallet-detail-container">
        <div className="wallet-detail-account-info">
          <div className="wallet-detail-title-wrapper">
            <h4 className="wallet-detail-title">내 지갑</h4>
            <WalletStatus desc={TOKEN_DETAIL_CONFIG[tokenDetailType]?.blockWalletStatusDesc} />
          </div>
          <div className="wallet-detail-address-wrapper">
            <span className="wallet-detail-address">
              {selectedWallet?.aliasNm ?? selectedWallet?.dfltAliasNm}
            </span>
            <button type="button" aria-label="복사하기" className="btn-wallet-detail-copy" onClick={copyWalletAddress}>
              <i className="icon-wallet-detail-copy" aria-hidden="true"></i>
            </button>
          </div>
          <div className="wallet-detail-account-wrapper">
            <span className="wallet-detail-account-label">연계계좌</span>
            <span className="wallet-detail-account-value">
              {shortBankName} {selectedWallet?.aliasNm ?? selectedWallet?.dfltAliasNm}
            </span>
          </div>
        </div>
        <div className="wallet-detail-more-wrapper">
          <button type="button" aria-label="더보기" className="btn-wallet-detail-more" onClick={onOpenMoreMenu}>
            <i aria-hidden="true" className="icon-wallet-detail-more"></i>
          </button>
        </div>
      </section>

      <section className="wallet-detail-token-container">
        <span className="wallet-detail-token-title">{TOKEN_LABEL[latestCoinItem.type]}</span>
        <span className="wallet-detail-token-value">
          {Number(latestCoinItem?.amt).toLocaleString()}
          <span className="wallet-detail-token-won">원</span>
        </span>
        {isDisabled && (
          <span className="wallet-detail-token-status-wrapper">
            <i className="icon-wallet-detail-token-status" aria-hidden="true"></i>
            <span className="wallet-detail-token-status">
              {TOKEN_DETAIL_CONFIG[tokenDetailType]?.blockWalletStatusDesc}
            </span>
          </span>
        )}
      </section>

      <FunctionButtons item={latestCoinItem} openQRScanner={openQRScanner} disabled={isDisabled} />
    </>
  );
};

export const AssetDetailInfo = memo(function AssetDetailInfo({
  coinId,
  openQRScanner,
  isDisabled,
  selectedWallet,
  onOpenMoreMenu,
}: Props) {
  return (
    <ErrorBoundary fallback={FallbackErrorMessage}>
      <Suspense
        fallback={
          <AssetDetailLoader
            coinId={coinId}
            openQRScanner={openQRScanner}
            isDisabled={isDisabled}
            selectedWallet={selectedWallet}
            onOpenMoreMenu={onOpenMoreMenu}
          />
        }
      >
        <AssetDetailLoader
          coinId={coinId}
          openQRScanner={openQRScanner}
          isDisabled={isDisabled}
          selectedWallet={selectedWallet}
          onOpenMoreMenu={onOpenMoreMenu}
        />
      </Suspense>
    </ErrorBoundary>
  );
});
