import { format, parse } from 'date-fns';
import { memo, useCallback, useMemo } from 'react';
import { useWalletSearchParams } from '~/entities/wallet/lib/use-wallet-search-params';
import i18n from '~/shared/i18n/i18n';
import { SelectStyle } from '~/shared/ui/selects/base/types';
import { useSelectBottomSheet } from '~/shared/ui/selects/use-select-bottom-sheet';

export const MonthSelect = memo(function MonthSelect() {
  const { searchParams, updateSearchParams, getStDt, getEdDt } = useWalletSearchParams();

  const dates = useMemo(() => {
    return new Array(12).fill(null).map((_, index) => {
      const date = new Date();
      date.setDate(1);
      date.setMonth(date.getMonth() - index);
      return date;
    });
  }, []);

  const values = useMemo(() => dates.map((date) => format(date, 'yyyy-MM')), [dates]);
  const labels = useMemo(() => dates.map((date) => format(date, 'yyyy년 M월')), [dates]);

  const selectedDate = useMemo(() => {
    if (searchParams.stDt) {
      return parse(searchParams.stDt, 'yyyy-MM-dd', new Date());
    }
    return new Date();
  }, [searchParams.stDt]);

  const selectedLabel = format(selectedDate, 'yyyy년 M월');
  const selectedValue = format(selectedDate, 'yyyy-MM');

  const { openSelectBottomSheet, closeBottomSheet } = useSelectBottomSheet<string>();

  const handleMonthChange = useCallback(
    (dateOrDirection: Date | 'prev' | 'next') => {
      const newDate =
        dateOrDirection instanceof Date
          ? dateOrDirection
          : (() => {
              const date = new Date(selectedDate);
              date.setMonth(selectedDate.getMonth() + (dateOrDirection === 'prev' ? -1 : 1));
              return date;
            })();

      updateSearchParams({
        stDt: getStDt(newDate),
        edDt: getEdDt(newDate),
      });
    },
    [selectedDate, updateSearchParams, getStDt, getEdDt],
  );

  const handleOpenMonthList = useCallback(() => {
    openSelectBottomSheet({
      title: i18n.t('selectInquiryPeriod'),
      description: i18n.t('text:recentYearTransactionsOnly'),
      options: values.map((value, index) => ({
        value,
        label: labels[index],
      })),
      selectedOption: {
        value: selectedValue,
        label: selectedLabel,
      },
      selectStyle: SelectStyle.DEFAULT,
      onRadioChange: ({ option }) => {
        const newDate = parse(option.label, 'yyyy년 M월', new Date());
        handleMonthChange(newDate);
        closeBottomSheet();
      },
    });
  }, [openSelectBottomSheet, values, labels, selectedValue, selectedLabel, closeBottomSheet, handleMonthChange]);

  const displayYear = format(selectedDate, 'yyyy');
  const displayMonth = format(selectedDate, 'M');

  return (
    <div className="wallet-detail-date-wrapper">
      <button type="button" className="btn-wallet-detail-date" onClick={handleOpenMonthList}>
        <span className="wallet-detail-date">
          {displayYear}<span className="kbfg-text">년</span> {displayMonth}<span className="kbfg-text">월</span>
        </span>
        <i className="icon-wallet-detail-date-down"></i>
      </button>
    </div>
  );
});
